import Foundation

/// Catalog of commercial-grade responsive typography & reader CSS themes
/// extracted and adapted from the official SourceRead iOS application.
/// Ideal for HTML/EPUB rendering and WKWebView article presentation.
enum SakuraThemeCatalog {
    enum Theme: String, CaseIterable, Sendable {
        case classic = "sakura"
        case dark = "sakura-dark"
        case solarized = "sakura-dark-solarized"
        case earthly = "sakura-earthly"
        case ink = "sakura-ink"
        case vader = "sakura-vader"

        var displayName: String {
            switch self {
            case .classic: return "经典樱白"
            case .dark: return "极夜幽黑"
            case .solarized: return "暗夜暖阳"
            case .earthly: return "大地护眼"
            case .ink: return "水墨高对比"
            case .vader: return "深渊纯黑"
            }
        }
    }

    static func css(for theme: Theme) -> String {
        let themeCSS: String
        switch theme {
        case .classic: themeCSS = sakuraCSS
        case .dark: themeCSS = sakuraDarkCSS
        case .solarized: themeCSS = sakuraSolarizedCSS
        case .earthly: themeCSS = sakuraEarthlyCSS
        case .ink: themeCSS = sakuraInkCSS
        case .vader: themeCSS = sakuraVaderCSS
        }
        return normalizeCSS + "\n" + themeCSS
    }

